<script setup lang="ts">import { getColorChannelConfig } from '@fex-design/core/color-picker/channels';import { positionToValue } from '@fex-design/core/color-picker/coordinates';import type { ColorChannel } from '@fex-design/core/color-picker/types';import { colorPickerChannelClassName } from '@fex-design/styles/color-picker';import { cn } from '@fex/utils';import { computed,provide,ref,useAttrs } from 'vue';import { colorChannelKey,useColorPicker } from './context';defineOptions({inheritAttrs:false});const props=withDefaults(defineProps<{channel:ColorChannel;orientation?:'horizontal'|'vertical'}>(),{orientation:'horizontal'}),attrs=useAttrs(),root=ref<HTMLDivElement>(),context=useColorPicker();provide(colorChannelKey,computed(()=>props.channel));const background=computed(()=>props.channel.endsWith('hue')?'linear-gradient(to right,red,#ff0,lime,cyan,blue,#f0f,red)':props.channel==='alpha'?`linear-gradient(to right,transparent,${context.snapshot.value.value?.toString('rgb')??'transparent'})`:`linear-gradient(to right,black,${context.snapshot.value.value?.toString('rgb')??'transparent'},white)`);function update(e:PointerEvent){if(!root.value)return;const r=root.value.getBoundingClientRect(),p=props.orientation==='vertical'?1-(e.clientY-r.top)/r.height:(e.clientX-r.left)/r.width,c=getColorChannelConfig(props.channel);context.controller.setChannel(props.channel,positionToValue(Math.min(1,Math.max(0,p)),c.min,c.max))}function down(e:PointerEvent){if(context.snapshot.value.disabled)return;(e.currentTarget as HTMLElement).setPointerCapture(e.pointerId);context.controller.beginInteraction({source:'channel'});update(e)}function move(e:PointerEvent){if((e.currentTarget as HTMLElement).hasPointerCapture(e.pointerId))update(e)}function up(e:PointerEvent){const el=e.currentTarget as HTMLElement;if(el.hasPointerCapture(e.pointerId)){el.releasePointerCapture(e.pointerId);context.controller.completeInteraction()}}</script><template><div v-bind="attrs" ref="root" :data-disabled="context.snapshot.value.disabled||undefined" :data-orientation="props.orientation" :class="cn(colorPickerChannelClassName,attrs.class as string|undefined)" :style="[{'--color-picker-channel-background':background},attrs.style]" @pointerdown="down" @pointermove="move" @pointerup="up"><slot /></div></template>
